package cn.servicehub.workflow.team;import cn.servicehub.audit.AuditEvent;import cn.servicehub.audit.AuditEventPublisher;import cn.servicehub.security.CurrentUser;import cn.servicehub.workflow.application.WorkflowConflictException;import java.time.Instant;import java.util.Map;import java.util.Set;import java.util.UUID;import org.slf4j.MDC;import org.springframework.security.access.AccessDeniedException;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
@Service public class SupportQueueReconciliationService{private final SupportQueueCommandRepository commands;private final SupportQueueReconciliationRepository requests;private final SupportQueueService queues;private final SupportQueueRepository queueRepo;private final SupportQueueMigrationRepository plans;private final AuditEventPublisher audit;public SupportQueueReconciliationService(SupportQueueCommandRepository c,SupportQueueReconciliationRepository r,SupportQueueService q,SupportQueueRepository qr,SupportQueueMigrationRepository p,AuditEventPublisher a){commands=c;requests=r;queues=q;queueRepo=qr;plans=p;audit=a;}
 @Transactional public SupportQueueReconciliationRequest request(String target,String key,long commandVersion,String decision,String type,String id,String reason){CurrentUser actor=queues.migrationActor();SupportQueueCommandRecord c=commands.find(target,key).orElseThrow(WorkflowConflictException::new);queues.migrationQueue(actor,c.resourceCode().split(":")[0]);if(c.version()!=commandVersion||!"RECONCILIATION_REQUIRED".equals(c.status())||!"LEGACY_UNVERIFIABLE".equals(c.keyVersion())||!Set.of("LEGACY_RESULT_ONLY","FAILED_FINAL").contains(decision)||reason==null||reason.trim().length()<4)throw new WorkflowConflictException();if("LEGACY_RESULT_ONLY".equals(decision)&&!strong(type,id))throw new WorkflowConflictException();SupportQueueReconciliationRequest r=new SupportQueueReconciliationRequest("SQRR-"+UUID.randomUUID().toString().replace("-",""),target,key,commandVersion,decision,type,id,reason.trim(),"PENDING",actor.iamUserId(),null,0,Instant.now(),null);requests.create(r);record(actor,"SUPPORT_QUEUE_RECONCILIATION_REQUESTED",r.id());return r;}
 @Transactional public SupportQueueReconciliationRequest approve(String requestId,long expectedVersion,String reason){CurrentUser actor=queues.migrationActor();SupportQueueReconciliationRequest r=requests.find(requestId).orElseThrow(WorkflowConflictException::new);SupportQueueCommandRecord c=commands.find(r.targetActorIamUserId(),r.idempotencyKey()).orElseThrow(WorkflowConflictException::new);queues.migrationQueue(actor,c.resourceCode().split(":")[0]);if(r.version()!=expectedVersion||!"PENDING".equals(r.status())||actor.iamUserId().equals(r.requestedByIamUserId())||("LEGACY_RESULT_ONLY".equals(r.decision())&&!strong(r.resultResourceType(),r.resultResourceId())))throw new AccessDeniedException("Independent reconciliation approval is required");if(!commands.resolveReconciliation(r.targetActorIamUserId(),r.idempotencyKey(),r.commandVersion(),r.decision(),r.resultResourceType(),r.resultResourceId(),actor.iamUserId()))throw new WorkflowConflictException();SupportQueueReconciliationRequest done=new SupportQueueReconciliationRequest(r.id(),r.targetActorIamUserId(),r.idempotencyKey(),r.commandVersion(),r.decision(),r.resultResourceType(),r.resultResourceId(),r.reason(),"APPROVED",r.requestedByIamUserId(),actor.iamUserId(),r.version()+1,r.createdAt(),Instant.now());if(!requests.approve(done,r.version()))throw new WorkflowConflictException();record(actor,"SUPPORT_QUEUE_RECONCILIATION_APPROVED",r.id());return done;}
 private boolean strong(String type,String id){if(type==null||id==null)return false;if("support-queue".equals(type))return queueRepo.findByCode(id).isPresent();if("support-queue-migration".equals(type))return plans.findPlan(id).isPresent();return false;}private void record(CurrentUser a,String action,String id){audit.publish(new AuditEvent(Instant.now(),MDC.get("requestId")==null?"system":MDC.get("requestId"),a.iamUserId(),action,"support-queue-reconciliation",id,Map.of()));}}
